env_names = ["XSOLLA_MERCHANT_ID", "XSOLLA_PROJECT_ID", "XSOLLA_PROJECT_API_KEY", "XSOLLA_QP_ENV"]
env_vars = {}

# Check process environment
process_env = {k: os.environ.get(k) for k in env_names}
if all(process_env.get(k) for k in env_names[:3]):
    env_vars = process_env
    source = "process environment"
else:
    # Check .env file
    try:
        env_text = pathlib.Path(".env").read_text()
        file_env = {}
        for line in env_text.splitlines():
            if "=" in line and not line.lstrip().startswith("#"):
                k, v = line.split("=", 1)
                file_env[k.strip()] = v.strip()
        if all(file_env.get(k) for k in env_names[:3]):
            env_vars = file_env
            source = ".env file"
    except:
        pass

if all(env_vars.get(k) for k in env_names[:3]):
    print(f"✓ Credentials found from {source}")
    print(f"Merchant: {env_vars.get(\"XSOLLA_MERCHANT_ID\")}")
    print(f"Project: {env_vars.get(\"XSOLLA_PROJECT_ID\")}")
    qp_env = env_vars.get("XSOLLA_QP_ENV", "production")
    if not qp_env or qp_env == "production":
        qp_env = "production"
    print(f"Environment: {qp_env}")
else:
    print("✗ Credentials not found")
'

