print(env['XSOLLA_MERCHANT_ID'] + ':' + env['XSOLLA_PROJECT_API_KEY'])
PYEOF
} | {
  read cred
  merchant=$(python3 -c "import pathlib; e=dict(l.split('=',1) for l in pathlib.Path('.env').read_text().splitlines() if '=' in l and not l.lstrip().startswith('#')); print(e['XSOLLA_MERCHANT_ID'])")
  project=$(python3 -c "import pathlib; e=dict(l.split('=',1) for l in pathlib.Path('.env').read_text().splitlines() if '=' in l and not l.lstrip().startswith('#')); print(e['XSOLLA_PROJECT_ID'])")
  qp_env=$(python3 -c "import pathlib; e=dict(l.split('=',1) for l in pathlib.Path('.env').read_text().splitlines() if '=' in l and not l.lstrip().startswith('#')); print(e.get('XSOLLA_QP_ENV', 'production'))")

  echo "user = \"$cred\"" | curl -sS -K - "https://quests-platform.xsolla.com/api/v2/merchants/$merchant/projects/$project" | python3 -m json.tool
}

